mapper.select:
SELECT id AS profile_id, user_id, display_name AS profile_name, template_version_id,
       CAST(client_types AS CHAR) AS client_types_json, enabled, revoked_at, valid_from, valid_until
FROM iam_authorization_profile
WHERE id > #{afterProfileId}

    AND user_id = #{userId}


    AND template_version_id = #{templateVersionId}


    AND enabled = #{enabled}


    AND (revoked_at IS NOT NULL) = #{revoked}


    AND JSON_CONTAINS(client_types, JSON_QUOTE(#{clientType}))

ORDER BY id LIMIT #{limit}
